      RAISE EXCEPTION '357_bot:policy_parity:% actual:%',c,actual;
    END IF;
    IF private.three_five_seven_bot_fold_probability(c->'cards',(c->>'round')::integer,c->>'aggression',false,0)<>0
       OR private.three_five_seven_bot_fold_probability(c->'cards',(c->>'round')::integer,c->>'aggression',false,100)<>100
    THEN RAISE EXCEPTION '357_bot:fixed_mode_did_not_override_strength'; END IF;
  END LOOP;
  cards:='[{"rank":"A","suit":"♠"},{"rank":"K","suit":"♥"},{"rank":"9","suit":"♦"}]';
  IF private.three_five_seven_bot_fold_probability(cards,1,'unknown',true,100)<>55
     OR private.three_five_seven_bot_fold_probability(cards,1,NULL,NULL,0)<>55
     OR private.three_five_seven_bot_fold_probability(cards,1,'normal',false,-1)<>0
     OR private.three_five_seven_bot_fold_probability(cards,1,'normal',false,101)<>100
     OR private.three_five_seven_bot_fold_probability(cards,1,'normal',false,NULL)<>30
  THEN RAISE EXCEPTION '357_bot:defaults_or_clamps'; END IF;
  IF private.three_five_seven_bot_fold_probability(NULL,1,'normal',true,0) IS NOT NULL
     OR private.three_five_seven_bot_fold_probability('{}',1,'normal',true,0) IS NOT NULL
     OR private.three_five_seven_bot_fold_probability('[]',1,'normal',true,0) IS NOT NULL
     OR private.three_five_seven_bot_fold_probability(cards,2,'normal',true,0) IS NOT NULL
     OR private.three_five_seven_bot_fold_probability(cards,4,'normal',false,0) IS NOT NULL
     OR private.three_five_seven_bot_fold_probability('[{},{},{}]',1,'normal',false,0) IS NOT NULL
  THEN RAISE EXCEPTION '357_bot:invalid_cards_were_used'; END IF;
  IF has_function_privilege('anon','private.three_five_seven_bot_fold_probability(jsonb,integer,text,boolean,numeric)','EXECUTE')
     OR has_function_privilege('authenticated','private.three_five_seven_bot_fold_probability(jsonb,integer,text,boolean,numeric)','EXECUTE')
  THEN RAISE EXCEPTION '357_bot:policy_is_public'; END IF;
END;
$policy$;

DO $integration$
DECLARE
  users uuid[]; g uuid:=gen_random_uuid(); d uuid:=gen_random_uuid(); r uuid;
  human uuid; bot uuid; saved_card jsonb; before_player jsonb; result jsonb;
  old_fixed integer; old_strength boolean; cursor_before bigint;
BEGIN
  SELECT array_agg(id ORDER BY created_at,id) INTO users FROM (
    SELECT p.id,p.created_at FROM public.profiles p
    WHERE EXISTS(SELECT 1 FROM auth.users u WHERE u.id=p.id)
      AND NOT public.has_role(p.id,'admin'::public.app_role)
    ORDER BY p.created_at,p.id LIMIT 2
  ) p;
  IF cardinality(users)<>2 THEN RAISE EXCEPTION '357_bot:requires_two_profiles'; END IF;
  SELECT bot_fold_probability,bot_use_hand_strength INTO old_fixed,old_strength
    FROM public.game_defaults WHERE game_type='3-5-7';
  PERFORM set_config('request.jwt.claim.role','authenticated',true);
  PERFORM set_config('request.jwt.claim.sub',users[1]::text,true);
  PERFORM set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',users[1])::text,true);
  PERFORM set_config('app.three_five_seven_authoritative_write','on',true);
  PERFORM set_config('app.three_five_seven_test_no_sweep','on',true);
  INSERT INTO public.games(id,name,status,game_type,current_game_uuid,current_host,dealer_position,
    ante_amount,rollover_amount,leg_value,legs_to_win,total_hands,pot,real_money)
  VALUES(g,'Codex rollback proof - 357 bot policy','ante_decision','3-5-7',d,users[1],1,0,1,1,3,0,0,false);
  INSERT INTO public.dealer_games(id,session_id,dealer_user_id,game_type) VALUES(d,g,users[1],'3-5-7');
  INSERT INTO public.players(game_id,user_id,position,chips,status,sitting_out,is_bot,ante_decision) VALUES
    (g,users[1],1,100,'active',false,false,'ante_up'),(g,users[2],2,100,'active',false,true,'ante_up');
  SELECT id INTO human FROM public.players WHERE game_id=g AND user_id=users[1];
  SELECT id INTO bot FROM public.players WHERE game_id=g AND user_id=users[2];
  result:=public.three_five_seven_begin_game(g);r:=(result->>'round_id')::uuid;
  IF r IS NULL THEN RAISE EXCEPTION '357_bot:bootstrap:%',result; END IF;
  UPDATE public.rounds SET decision_deadline=clock_timestamp()+interval '10 minutes' WHERE id=r;
  SELECT to_jsonb(c) INTO saved_card FROM public.player_cards c WHERE player_id=bot AND round_id=r;
  DELETE FROM public.player_cards WHERE player_id=bot AND round_id=r;
  UPDATE public.game_defaults SET bot_use_hand_strength=true,bot_fold_probability=0 WHERE game_type='3-5-7';
  PERFORM private.three_five_seven_recover_game(g);
  IF (SELECT coalesce(decision_locked,false) OR current_decision IS NOT NULL FROM public.players WHERE id=bot)
  THEN RAISE EXCEPTION '357_bot:missing_cards_decided'; END IF;
  INSERT INTO public.player_cards SELECT * FROM jsonb_populate_record(NULL::public.player_cards,saved_card);
  UPDATE public.player_cards SET cards='[{"rank":"A","suit":"♠"},{"rank":"A","suit":"♥"},{"rank":"A","suit":"♦"}]' WHERE player_id=bot AND round_id=r;
  UPDATE public.players SET sitting_out=true WHERE id=bot;
  PERFORM private.three_five_seven_recover_game(g);
  IF (SELECT coalesce(decision_locked,false) FROM public.players WHERE id=bot) THEN RAISE EXCEPTION '357_bot:sitting_out_decided'; END IF;
  UPDATE public.players SET sitting_out=false WHERE id=bot;
  UPDATE public.games SET is_paused=true WHERE id=g;
  result:=private.three_five_seven_recover_game(g);
  IF result->>'outcome'<>'paused' OR (SELECT coalesce(decision_locked,false) FROM public.players WHERE id=bot)
  THEN RAISE EXCEPTION '357_bot:pause_not_preserved'; END IF;
  UPDATE public.games SET is_paused=false WHERE id=g;

  -- In strength mode the strong hand stays even with a hidden fixed 100%.
  UPDATE public.game_defaults SET bot_fold_probability=100 WHERE game_type='3-5-7';
  PERFORM private.three_five_seven_recover_game(g);
  IF NOT (SELECT decision_locked AND current_decision='stay' FROM public.players WHERE id=bot)
     OR (SELECT coalesce(decision_locked,false) OR current_decision IS NOT NULL FROM public.players WHERE id=human)
  THEN RAISE EXCEPTION '357_bot:hand_strength_or_human_isolation'; END IF;
  SELECT to_jsonb(p) INTO before_player FROM public.players p WHERE id=bot;
  PERFORM private.three_five_seven_recover_game(g);
  IF (SELECT to_jsonb(p) FROM public.players p WHERE id=bot) IS DISTINCT FROM before_player
  THEN RAISE EXCEPTION '357_bot:recovery_replay_changed_locked_decision'; END IF;

  -- Switching mode does not rewrite a locked decision; the next undecided
  -- action follows the configured fixed percentage without aggression.
  UPDATE public.game_defaults SET bot_use_hand_strength=false WHERE game_type='3-5-7';
  PERFORM private.three_five_seven_recover_game(g);
  IF (SELECT current_decision FROM public.players WHERE id=bot)<>'stay' THEN RAISE EXCEPTION '357_bot:mode_change_replayed_decision'; END IF;
  DELETE FROM public.player_actions WHERE round_id=r AND player_id=bot;
  UPDATE public.players SET decision_locked=false,current_decision=NULL WHERE id=bot;
  PERFORM private.three_five_seven_recover_game(g);
  IF (SELECT current_decision FROM public.players WHERE id=bot)<>'fold' THEN RAISE EXCEPTION '357_bot:fixed_100_did_not_fold'; END IF;
  DELETE FROM public.player_actions WHERE round_id=r AND player_id=bot;
  UPDATE public.players SET decision_locked=false,current_decision=NULL WHERE id=bot;
  UPDATE public.game_defaults SET bot_fold_probability=0 WHERE game_type='3-5-7';
  PERFORM private.three_five_seven_recover_game(g);
  IF (SELECT current_decision FROM public.players WHERE id=bot)<>'stay' THEN RAISE EXCEPTION '357_bot:fixed_0_did_not_stay'; END IF;
  IF (SELECT sum(chips) FROM public.players WHERE game_id=g)<>200
     OR EXISTS(SELECT 1 FROM private.three_five_seven_round_resolutions WHERE game_id=g)
  THEN RAISE EXCEPTION '357_bot:decision_only_changed_finances'; END IF;
  UPDATE public.game_defaults SET bot_use_hand_strength=old_strength,bot_fold_probability=old_fixed WHERE game_type='3-5-7';
  PERFORM set_config('app.three_five_seven_recovery','off',true);
END;
$integration$;

ROLLBACK;
